on conflict(id) do nothing;

select 'atv_'||id,'tenant_raeburn_group',id,1,jsonb_build_object('name',name,'type',type,'instructions',instructions,'rubric',rubric,'accessibilityOptions',accessibility_options,'version',1),'seed'
from assessment_templates where tenant_id='tenant_raeburn_group'
on conflict(tenant_id,template_id,version) do nothing;